      .map((k) => args[k])
      .find((v): v is string => typeof v === "string")!;

    let searchText = "";
    if (typeof args.content === "string") searchText += args.content + "\n";
    if (Array.isArray(args.edits)) {
      for (const edit of args.edits) {
        if (typeof edit.oldText === "string") searchText += edit.oldText + "\n";
        if (typeof edit.newText === "string") searchText += edit.newText + "\n";
      }
    }
    if (typeof args.oldText === "string" && !Array.isArray(args.edits)) searchText += args.oldText + "\n";
    if (typeof args.newText === "string" && !Array.isArray(args.edits)) searchText += args.newText + "\n";

