const VAGUE_GOAL_RE = /^(yea?h?|yes|right|ok|alright|sure|fine|good|great|nice|perfect|works?|got it|makes sense|that('s| is| was) .{0,60}|this (must be|should be|is the) .{0,60})[.!?]*$/i;

// Reject lines that are clearly not user goals (pasted output, code, paths, tool dumps)
// or meta-prompt boilerplate (command templates like `/issues` that start with "For each issue:"
// followed by numbered "Read the issue in full..." steps).
// Also reject lines that are remnants of a previous compaction summary (section content
// like "Objective:", truncation markers like "...(N omitted)", quoted leftover fragments).
const NON_GOAL_RE = new RegExp([
  /^\s*[\[│├└─╭╰]/.source,
  /```/.source,
  /^\s*(=[A-Z]+\(|function |const |let |var |import |export |class )/.source,
  /^(https?:|file:|\/[A-Za-z])/.source,
  /\\n/.source,
  /^\s*For each\b/.source,
  /\bin full\b[^\n]*\b(comments|issue|issues|PRs?|linked)\b/.source,
  // Compaction summary section headers — trivially not goals
  /^\s*(Objective:|Type:|Scope:|Modified:|Created:|Read:|Session type:|Active files:|Open items:|User Preferences:|Active Context:|Constraints:|Decisions:|Commits:|Files And Changes|Session|Session Goal|Outstanding Context)\b/.source,
