/**
 * Content classification — tags normalized blocks as critical, contextual,
 * or ephemeral based on their content type and density.
 *
 * Used by capBrief (token-budget-aware truncation) to decide which content
 * to prioritize when reducing the brief transcript.
 */

import type { NormalizedBlock } from "../types";

export type ContentClass = "critical" | "contextual" | "ephemeral";

// ── density scoring ──

/**
 * Score content density algorithmically (0 = empty, higher = denser).
 * Used to distinguish substantive tool results from trivial ones.
 */
export const contentDensity = (text: string): number => {
  let score = 0;

  // Code blocks: +3 each
  const codeBlocks = text.match(/```/g);
  if (codeBlocks) score += Math.min(codeBlocks.length, 3) * 3;

  // File paths: +1 each, up to 5
  const paths = text.match(/[\w./-]+\.[\w]+/g);
  if (paths) score += Math.min(paths.length, 5);

  // URLs: +1 each, up to 3
  const urls = text.match(/https?:\/\/[^\s]+/g);
  if (urls) score += Math.min(urls.length, 3);

  // Key:value pairs (structured data): +1
  if (/["']?\w+["']?\s*:\s*["']?\w+["']?/.test(text)) score += 1;

  // Line count (dense content): +1 per 20 lines, up to 3
  const lines = text.split("\n").length;
  score += Math.min(Math.floor(lines / 20), 3);

  return score;
};

// ── acknowledgment detection ──

const ACK_RE = /^(ok|okay|sure|yeah|yep|got it|gotcha|i'll do that|on it|will do|done|thanks|thx|👍|✅)\s*[.!]*$/i;

const isAck = (text: string): boolean => ACK_RE.test(text.trim()) && text.length < 30;

// ── classification ──

export const classifyBlock = (b: NormalizedBlock): ContentClass => {
  switch (b.kind) {
    case "user":
      return "critical";

    case "tool_result":
      if (b.isError) return "critical";
      // Dense results (code, errors, structured data) are contextual
      if (contentDensity(b.text) >= 3) return "contextual";
      return "ephemeral";

    case "assistant":
      if (isAck(b.text)) return "ephemeral";
      // Assistant messages with tool calls or decision language are critical
      if (/\* (?:Edit|Write|Read|bash)"/.test(b.text)) return "critical";
      if (b.text.length > 100) return "contextual";
      return "critical";

    case "tool_call":
      return "critical";

    case "bash":
      return "contextual";

    case "thinking":
      return "ephemeral";

    default:
      return "contextual";
  }
};

