/**
 * OpenCode CLI fingerprint — pure functions for synthesizing the exact
 * headers that opencode CLI sends when using its `opencode` provider
 * (which maps to our `openzen` provider in pi).
 *
 * Based on the opencode source:
 *   packages/opencode/src/session/llm/request.ts — LLMRequestPrep.prepare()
 *
 * Zero pi imports — fully testable.
 */

import { createHash, randomUUID } from "crypto";

// ── Constants ────────────────────────────────────────────────────────────────
/**
 * The User-Agent pattern opencode CLI uses: `opencode/${VERSION}`.
 * VERSION comes from InstallationVersion which is OPENCODE_VERSION env var
 * or "local" when running from source.
 *
 * We use the latest known stable version as the default.
 */
export const USER_AGENT_PREFIX = "opencode/";
export const DEFAULT_USER_AGENT = "opencode/latest/1.18.18/cli";

/**
 * Default values that opencode CLI uses for `opencode` provider requests.
 * These are the exact values from the CLI source.
 */
export interface CliIdentity {
  /** x-opencode-client — from RuntimeFlags.client (default: "cli" from OPENCODE_CLIENT env). */
  client: string;
  /** x-opencode-project — from the active project ID. */
  project: string;
  /** User-Agent — from InstallationVersion. */
  userAgent: string;
}

const DEFAULT_CLI_IDENTITY: CliIdentity = {
  client: "cli",
  project: "/opencode",
  userAgent: DEFAULT_USER_AGENT,
};

// ── Stable session id ────────────────────────────────────────────────────────
/**
 * Derive a conversation-stable session id from a stable seed, shaped as a UUID.
 * The opencode CLI uses `input.sessionID` directly (a UUID from its session
 * creation), but for prompt-cache compatibility we derive a stable one from
 * a seed when available.
 */
export function stableSessionId(seed: string | undefined): string {
  if (!seed) return randomUUID();
  const hex = createHash("sha256").update(seed).digest("hex").slice(0, 32);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

// ── Header helpers ───────────────────────────────────────────────────────────
/**
 * Case-insensitive lookup for a header in a headers record.
 */
function findHeader(headers: Record<string, string>, name: string): string | undefined {
  return Object.entries(headers).find(([key]) => key.toLowerCase() === name.toLowerCase())?.[1];
}

/**
 * Set a User-Agent header with correct casing, removing any existing UA first.
 */
function setUserAgentHeader(headers: Record<string, string>, ua: string): void {
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === "user-agent") {
      delete headers[key];
    }
  }
  headers["User-Agent"] = ua;
}

// ── CLI header synthesis ────────────────────────────────────────────────────
/**
 * Build the exact set of headers that opencode CLI sends for its `opencode`
 * provider (which maps to our `openzen` provider in pi).
 *
 * From the opencode source (LLMRequestPrep.prepare):
 *   x-opencode-project: projectID (if providerID starts with "opencode")
 *   x-opencode-session: sessionID
 *   x-opencode-request: user.id
 *   x-opencode-client: flags.client
 *   User-Agent: opencode/${InstallationVersion}
 *
 * NOTE: x-session-affinity and X-Session-Id are sent for NON-opencode providers,
 * not for the opencode provider. See request.ts:187-193 (else branch).
 */
export function buildOpencodeProviderHeaders(
  identity: CliIdentity,
  sessionSeed: string,
  requestId: string,
  projectID?: string,
): Record<string, string> {
  const headers: Record<string, string> = {};

  // User-Agent — always set (opencode always sends this)
  setUserAgentHeader(headers, identity.userAgent);

  // x-opencode-project — use explicit projectID, fall back to identity.project
  const project = projectID ?? identity.project;
  if (project) {
    headers["x-opencode-project"] = project;
  }

  // x-opencode-session — derived from session seed (stable for prompt-cache)
  headers["x-opencode-session"] = stableSessionId(sessionSeed);

  // x-opencode-request — opencode uses user.id; we use the provided requestId
  headers["x-opencode-request"] = requestId;

  // x-opencode-client — from RuntimeFlags.client (default: "cli")
  headers["x-opencode-client"] = identity.client;

  return headers;
}

/**
 * Apply CLI identity defaults into existing headers.
 *
 * For `x-opencode-*` headers, existing values always win (defaults only fill
 * gaps). The User-Agent is the exception: a non-CLI client UA (curl, SDKs)
 * is replaced with the synthesized CLI UA, because opencode.ai's free tier
 * flags generic client UAs from datacenter IPs.
 */
export function applyCliDefaults(
  headers: Record<string, string>,
  identity: CliIdentity,
  sessionSeed?: string,
  requestId?: string,
  projectID?: string,
): void {
  // User-Agent — replace non-CLI UAs
  const existingUa = headers["User-Agent"] || headers["user-agent"];
  const isCliLike =
    typeof existingUa === "string" && existingUa.trim().startsWith(USER_AGENT_PREFIX);

  if (!isCliLike) {
    setUserAgentHeader(headers, identity.userAgent);
  }

  // x-opencode-* headers — fill gaps, never overwrite
  headers["x-opencode-client"] ||= identity.client;
  headers["x-opencode-project"] ||= projectID ?? identity.project;
  headers["x-opencode-request"] ||= requestId ?? randomUUID();
  headers["x-opencode-session"] ||= stableSessionId(sessionSeed);
}

// ── Forward / merge ─────────────────────────────────────────────────────────
const OPENCODE_HEADER_KEYS = [
  "x-opencode-session",
  "x-opencode-request",
  "x-opencode-project",
  "x-opencode-client",
] as const;

export interface ForwardOptions {
  synthesizeRequestId?: boolean;
  sessionSeed?: string;
  identity?: CliIdentity;
  requestId?: string;
  projectID?: string;
}

/**
 * Forward OpenCode client request metadata headers to the upstream provider,
 * optionally synthesizing CLI identity headers when absent.
 *
 * This mirrors the opencode CLI's behavior: it copies the x-opencode-* headers
 * from the incoming request (set by LLMRequestPrep) and adds any missing ones
 * from the CLI defaults.
 */
export function forwardOpencodeClientHeaders(
  headers: Record<string, string>,
  clientHeaders: Record<string, string>,
  options?: ForwardOptions,
): void {
  // 1. Forward User-Agent from client
  const clientUA = clientHeaders["User-Agent"] || clientHeaders["user-agent"];
  if (clientUA) {
    setUserAgentHeader(headers, clientUA);
  }

  // 2. Forward x-opencode-* metadata headers (case-insensitive)
  for (const headerName of OPENCODE_HEADER_KEYS) {
    const value = findHeader(clientHeaders, headerName);
    if (value) {
      headers[headerName] = value;
    }
  }

  // 3. Synthesize session/request id from fallback headers
  if (options?.synthesizeRequestId && !headers["x-opencode-session"]) {
    const sessionAffinity =
      findHeader(clientHeaders, "x-session-affinity") ?? findHeader(clientHeaders, "x-session-id");
    if (sessionAffinity) {
      headers["x-opencode-session"] = sessionAffinity;
      if (!headers["x-opencode-request"]) {
        headers["x-opencode-request"] = randomUUID();
      }
    }
  }

  // 4. Synthesize the OpenCode CLI identity (OpencodeExecutor path)
  //    — replaces non-CLI UAs, fills gaps in x-opencode-* headers
  if (options?.identity) {
    applyCliDefaults(
      headers,
      options.identity,
      options.sessionSeed,
      options.requestId,
      options.projectID,
    );
  }
}

// ── Fingerprint builder (high-level) ────────────────────────────────────────
export interface FingerprintConfig {
  enabled: boolean;
  synthesizeHeaders: boolean;
  /** User-Agent prefix + version (default: "opencode/latest/1.18.18/cli"). */
  userAgent: string;
  /** x-opencode-client value (default: "cli"). */
  client: string;
  /** x-opencode-project value (default: "/opencode"). */
  project: string;
  /** When true, x-opencode-session is derived from connectionId seed. */
  stableSession: boolean;
}

/**
 * Build the final set of opencode CLI fingerprint headers to inject.
 * Returns only the headers that need to be set (no no-ops).
 *
 * This is the high-level API used by the extension hook.
 */
export function buildFingerprintHeaders(
  config: FingerprintConfig,
  sessionSeed: string,
  requestId: string,
  projectID?: string,
): Record<string, string> {
  if (!config.enabled || !config.synthesizeHeaders) {
    return {};
  }

  const identity: CliIdentity = {
    userAgent: config.userAgent || DEFAULT_USER_AGENT,
    client: config.client || DEFAULT_CLI_IDENTITY.client,
    project: config.project || DEFAULT_CLI_IDENTITY.project,
  };

