/**
 * pi-session-name — session branch extraction utilities.
 */

import type { DialoguePart } from "./types.ts";

export function blockText(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .filter(
      (b: unknown): b is { type: string; text: string } =>
        typeof b === "object" && b !== null && (b as Record<string, unknown>).type === "text",
    )
    .map((b) => b.text.trim())
    .filter(Boolean)
    .join(" ")
    .trim();
}

/**
 * Like blockText, but formats tool_calls as [tool:name args:...]
 * and skips tool_result blocks entirely.
 * Tool results (file contents, command outputs) are enormous and don't help with naming.
 */
export function blockTextWithoutToolResults(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  const parts: string[] = [];
  for (const block of content as Array<Record<string, unknown>>) {
    if (typeof block !== "object" || block === null) continue;
    if (block.type === "text") {
      const text = String(block.text ?? "").trim();
      if (text) parts.push(text);
    } else if (block.type === "toolCall") {
      const name = String(block.name ?? "unknown_tool");
      const args = JSON.stringify(block.arguments ?? {});
      parts.push(`[tool:${name} args:${args}]`);
    }
    // Non-text, non-toolCall blocks (thinking, image, etc): skip entirely

