export function renderSpillBlock(label: string, result: SpillResult): string {
  if ("inline" in result) return result.inline;
  const header = `${label} (${result.totalLines} total, ${formatBytes(result.totalBytes)}): written to ${result.file} — read this file for the full list. First ${result.previewLines} lines:`;
  return header + "\n" + result.preview;

